def lengthOfLIS(nums):
    # 贪心 + 二分：tails[i] 记录长度为 i+1 的递增子序列的最小末尾值
    tails = []
    for x in nums:
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(x)
        else:
            tails[lo] = x
    return len(tails)

