class Solution {
public:
    bool canPartition(vector<int>& nums) {
        long long total = 0;
        for (int v : nums) total += v;
        if (total % 2 == 1) return false;
        int target = (int)(total / 2);
        // 0/1 背包：dp[s] 表示能否凑出和 s
        vector<bool> dp(target + 1, false);
        dp[0] = true;
        for (int v : nums) {
            for (int s = target; s >= v; s--) {
                if (dp[s - v]) dp[s] = true;
            }
        }
        return dp[target];
    }
};

